-- Additive parametric scene pipeline. Private evidence never enters the public manifest.
begin;
-- Replaced by migration 004 when mandatory MFA is configured.
do $bootstrap$ begin if to_regprocedure('public.gp_moderation_allowed()') is null then execute $create$create function public.gp_moderation_allowed() returns boolean language sql stable security definer set search_path=public,pg_temp as $function$ select gp_verified() and coalesce(gp_role(),'') in ('moderator','admin') $function$$create$;end if;end $bootstrap$;
revoke all on function public.gp_moderation_allowed() from public,anon;grant execute on function public.gp_moderation_allowed() to authenticated;
create table public.parking_scene_sources(id uuid primary key,listing_id uuid not null references public.listings(id),owner_id uuid not null references auth.users(id),uploader_id uuid not null references auth.users(id),object_key text not null unique,mime text not null check(mime in ('application/pdf','image/webp')),byte_size integer not null check(byte_size between 20 and 10485760),sha256 text not null check(sha256 ~ '^[a-f0-9]{64}$'),created_at timestamptz not null default now());
create table public.parking_scenes(id uuid primary key default gen_random_uuid(),listing_id uuid not null references public.listings(id),owner_id uuid not null references auth.users(id),creator_id uuid not null references auth.users(id),manifest jsonb not null,evidence_ids uuid[] not null check(cardinality(evidence_ids) between 1 and 20),state text not null default 'pending_review' check(state in ('pending_review','approved','changes_requested','rejected','retired')),row_version integer not null default 1,approved_mapping jsonb,reviewed_at timestamptz,reviewer_id uuid references auth.users(id),review_reason text,review_checks jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index gp_scenes_listing_state on public.parking_scenes(listing_id,state,created_at desc);
create index gp_scene_sources_listing on public.parking_scene_sources(listing_id);
create function public.gp_scene_polygon(p jsonb) returns extensions.geometry language plpgsql immutable set search_path=public,pg_temp as $$declare v jsonb;points extensions.geometry[];poly extensions.geometry;begin
 if jsonb_typeof(p) is distinct from 'array' or jsonb_array_length(p) not between 3 and 64 then raise exception 'SCENE_INVALID';end if;
 for v in select * from jsonb_array_elements(p) loop
 if jsonb_typeof(v) is distinct from 'array' or jsonb_array_length(v)<>2 or jsonb_typeof(v->0) is distinct from 'number' or jsonb_typeof(v->1) is distinct from 'number' or (v->>0)::numeric not between -250 and 250 or (v->>1)::numeric not between -250 and 250 then raise exception 'SCENE_INVALID';end if;
 points=array_append(points,extensions.st_makepoint((v->>0)::float8,(v->>1)::float8));end loop;
 points=array_append(points,points[1]);poly=extensions.st_makepolygon(extensions.st_makeline(points));if not extensions.st_isvalid(poly) or extensions.st_area(poly)<0.05 then raise exception 'SCENE_INVALID';end if;return poly;
 end;$$;
create function public.gp_validate_scene(p jsonb) returns void language plpgsql set search_path=public,pg_temp as $$declare field text;shape jsonb;unit jsonb;point jsonb;d jsonb;floor extensions.geometry;accuracy numeric;actual numeric;begin
 if jsonb_typeof(p) is distinct from 'object' or p->>'schemaVersion' is distinct from '1.0' or p->>'unit' is distinct from 'm' or p->>'upAxis' is distinct from 'Y' or jsonb_typeof(p->'level') is distinct from 'number' or (p->>'level')::numeric not between -20 and 20 or trunc((p->>'level')::numeric)<>(p->>'level')::numeric then raise exception 'SCENE_INVALID';end if;
 for field in select jsonb_object_keys(p) loop if field not in ('schemaVersion','unit','upAxis','level','floor','spaces','contextSpaces','obstacles','provenance','observations') then raise exception 'SCENE_INVALID';end if;end loop;
 if jsonb_typeof(p->'floor') is distinct from 'object' or jsonb_typeof(p->'floor'->'thicknessM') is distinct from 'number' or (p->'floor'->>'thicknessM')::numeric not between 0.05 and 1 then raise exception 'SCENE_INVALID';end if;
 for field in select jsonb_object_keys(p->'floor') loop if field not in ('footprintXZ','thicknessM') then raise exception 'SCENE_INVALID';end if;end loop;floor=gp_scene_polygon(p->'floor'->'footprintXZ');
 foreach field in array array['spaces','contextSpaces','obstacles','observations'] loop if jsonb_typeof(p->field) is distinct from 'array' or jsonb_array_length(p->field)>(case when field='observations' then 100 else 500 end) then raise exception 'SCENE_INVALID';end if;end loop;if jsonb_array_length(p->'spaces')<1 then raise exception 'SCENE_INVALID';end if;
 for unit in select * from jsonb_array_elements(p->'spaces') loop
 if jsonb_typeof(unit) is distinct from 'object' or coalesce(unit->>'spaceId','')!~'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' or jsonb_typeof(unit->'displayNumber') is distinct from 'string' or length(unit->>'displayNumber') not between 1 and 30 or jsonb_typeof(unit->'dimensions') is distinct from 'object' then raise exception 'SCENE_INVALID';end if;
 for field in select jsonb_object_keys(unit) loop if field not in ('spaceId','displayNumber','footprintXZ','dimensions') then raise exception 'SCENE_INVALID';end if;end loop;
 for field in select jsonb_object_keys(unit->'dimensions') loop if field not in ('lengthM','widthM','clearanceM') then raise exception 'SCENE_INVALID';end if;end loop;
 foreach field in array array['lengthM','widthM','clearanceM'] loop if not(unit->'dimensions' ? field) then raise exception 'SCENE_INVALID';end if;if unit->'dimensions'->field<>'null'::jsonb and (jsonb_typeof(unit->'dimensions'->field) is distinct from 'number' or (unit->'dimensions'->>field)::numeric<=0 or (unit->'dimensions'->>field)::numeric>(case when field='clearanceM' then 20 else 50 end)) then raise exception 'SCENE_INVALID';end if;end loop;
 if not extensions.st_coveredby(gp_scene_polygon(unit->'footprintXZ'),floor) then raise exception 'SCENE_INVALID';end if;end loop;
 if (select count(*)<>count(distinct value->>'spaceId') from jsonb_array_elements(p->'spaces')) then raise exception 'SCENE_INVALID';end if;
 for shape in select * from jsonb_array_elements(p->'contextSpaces') loop if jsonb_typeof(shape) is distinct from 'object' or (select count(*) from jsonb_object_keys(shape))<>1 or not(shape ? 'footprintXZ') or not extensions.st_coveredby(gp_scene_polygon(shape->'footprintXZ'),floor) then raise exception 'SCENE_INVALID';end if;end loop;
 for shape in select * from jsonb_array_elements(p->'obstacles') loop
 if jsonb_typeof(shape) is distinct from 'object' or coalesce(shape->>'kind','') not in ('wall','column','ramp') or jsonb_typeof(shape->'heightM') is distinct from 'number' or (shape->>'heightM')::numeric not between 0.01 and 15 or jsonb_typeof(shape->'baseM') is distinct from 'number' or (shape->>'baseM')::numeric not between -5 and 15 or not extensions.st_coveredby(gp_scene_polygon(shape->'footprintXZ'),floor) then raise exception 'SCENE_INVALID';end if;
 for field in select jsonb_object_keys(shape) loop if field not in ('kind','footprintXZ','baseM','heightM','endHeightM') then raise exception 'SCENE_INVALID';end if;end loop;if shape ? 'endHeightM' and (jsonb_typeof(shape->'endHeightM') is distinct from 'number' or (shape->>'endHeightM')::numeric not between 0 and 15) then raise exception 'SCENE_INVALID';end if;end loop;
 if jsonb_typeof(p->'provenance') is distinct from 'object' or jsonb_typeof(p->'provenance'->'calibrated') is distinct from 'boolean' or jsonb_typeof(p->'provenance'->'observedAt') is distinct from 'string' or (p->'provenance'->>'observedAt')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}' or (p->'provenance'->>'observedAt')::timestamptz>now()+interval '5 minutes' or jsonb_typeof(p->'provenance'->'publicSummary') is distinct from 'string' or length(p->'provenance'->>'publicSummary') not between 10 and 400 or jsonb_typeof(p->'provenance'->'controlDistances') is distinct from 'array' or jsonb_array_length(p->'provenance'->'controlDistances')>10 then raise exception 'SCENE_INVALID';end if;
 for field in select jsonb_object_keys(p->'provenance') loop if field not in ('calibrated','accuracyM','controlDistances','observedAt','publicSummary') then raise exception 'SCENE_INVALID';end if;end loop;
 if p->'provenance'->>'calibrated'='true' then
 if jsonb_typeof(p->'provenance'->'accuracyM') is distinct from 'number' or ((p->'provenance'->>'accuracyM')::numeric<=0 or (p->'provenance'->>'accuracyM')::numeric>0.5) or jsonb_array_length(p->'provenance'->'controlDistances')<2 then raise exception 'SCENE_CALIBRATION_REQUIRED';end if;accuracy=(p->'provenance'->>'accuracyM')::numeric;
 if (select count(*)<>count(distinct least((value->'fromXZ')::text,(value->'toXZ')::text)||greatest((value->'fromXZ')::text,(value->'toXZ')::text)) from jsonb_array_elements(p->'provenance'->'controlDistances')) then raise exception 'SCENE_CALIBRATION_REQUIRED';end if;
 end if;
 for d in select * from jsonb_array_elements(p->'provenance'->'controlDistances') loop
 if jsonb_typeof(d) is distinct from 'object' or (select count(*) from jsonb_object_keys(d))<>3 or jsonb_typeof(d->'measuredM') is distinct from 'number' or (d->>'measuredM')::numeric not between 0.1 and 500 then raise exception 'SCENE_INVALID';end if;
 foreach field in array array['fromXZ','toXZ'] loop point=d->field;if jsonb_typeof(point) is distinct from 'array' or jsonb_array_length(point)<>2 or jsonb_typeof(point->0) is distinct from 'number' or jsonb_typeof(point->1) is distinct from 'number' or not extensions.st_covers(floor,extensions.st_makepoint((point->>0)::float8,(point->>1)::float8)) then raise exception 'SCENE_INVALID';end if;end loop;
 actual=sqrt(power((d->'toXZ'->>0)::numeric-(d->'fromXZ'->>0)::numeric,2)+power((d->'toXZ'->>1)::numeric-(d->'fromXZ'->>1)::numeric,2));if accuracy is not null and abs(actual-(d->>'measuredM')::numeric)>accuracy then raise exception 'SCENE_CALIBRATION_REQUIRED';end if;
 end loop;
 for d in select * from jsonb_array_elements(p->'observations') loop
 if jsonb_typeof(d) is distinct from 'object' or jsonb_typeof(d->'description') is distinct from 'string' or length(d->>'description') not between 3 and 500 or coalesce(d->>'category','') not in ('floor','humidity','lighting','access','obstacle','other') or jsonb_typeof(d->'positionXZ') is distinct from 'array' or jsonb_array_length(d->'positionXZ')<>2 or jsonb_typeof(d->'positionXZ'->0) is distinct from 'number' or jsonb_typeof(d->'positionXZ'->1) is distinct from 'number' or not extensions.st_covers(floor,extensions.st_makepoint((d->'positionXZ'->>0)::float8,(d->'positionXZ'->>1)::float8)) then raise exception 'SCENE_INVALID';end if;
 for field in select jsonb_object_keys(d) loop if field not in ('positionXZ','category','description') then raise exception 'SCENE_INVALID';end if;end loop;end loop;
 end;$$;
create function public.gp_scene_mapping(p jsonb,l jsonb,p_approval boolean default false) returns void language plpgsql set search_path=public,pg_temp as $$declare unit jsonb;ref jsonb;field text;begin
 if p_approval and (l->>'locationPrecision' is distinct from 'exact_opt_in' or p->'provenance'->>'calibrated' is distinct from 'true') then raise exception 'SCENE_CALIBRATION_REQUIRED';end if;
 if (select count(*) from jsonb_array_elements(l->'spaces') where (value->>'level')::integer=(p->>'level')::integer)<>jsonb_array_length(p->'spaces') then raise exception 'SCENE_MAPPING_INVALID';end if;
 for unit in select * from jsonb_array_elements(p->'spaces') loop
 select value into ref from jsonb_array_elements(l->'spaces') where value->>'id'=unit->>'spaceId' and value->>'number'=unit->>'displayNumber' and (value->>'level')::integer=(p->>'level')::integer;
 if ref is null then raise exception 'SCENE_MAPPING_INVALID';end if;
 foreach field in array array['lengthM','widthM','clearanceM'] loop if ref->field<>'null'::jsonb and (unit->'dimensions'->field='null'::jsonb or abs((unit->'dimensions'->>field)::numeric-(ref->>field)::numeric)>coalesce((p->'provenance'->>'accuracyM')::numeric,0.05)) then raise exception 'SCENE_MAPPING_INVALID';end if;end loop;end loop;
 end;$$;
create function public.gp_scene_create(p_listing_id uuid,p_manifest jsonb,p_evidence_ids uuid[],p_rights_attested boolean) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare l listings;s parking_scenes;begin
 if not gp_verified() then raise exception 'EMAIL_UNVERIFIED';end if;select * into l from listings where id=p_listing_id;if not found or (l.seller_id<>auth.uid() and not gp_moderation_allowed()) then raise exception 'NOT_FOUND';end if;
 if p_rights_attested is distinct from true or cardinality(p_evidence_ids) not between 1 and 20 or (select count(*) from parking_scene_sources x where x.id=any(p_evidence_ids) and x.listing_id=l.id and exists(select 1 from storage.objects o where o.bucket_id='scene-sources' and o.name=x.object_key))<>cardinality(p_evidence_ids) then raise exception 'SCENE_EVIDENCE_REQUIRED';end if;
 perform gp_validate_scene(p_manifest);perform gp_scene_mapping(p_manifest,l.draft,false);perform gp_limit('scene_submit',20,86400);
 insert into parking_scenes(listing_id,owner_id,creator_id,manifest,evidence_ids) values(l.id,l.seller_id,auth.uid(),p_manifest,p_evidence_ids) returning * into s;insert into audit_events(actor_id,action,target_id) values(auth.uid(),'scene.submit',s.id::text);return to_jsonb(s);
 end;$$;
create function public.gp_scene_review(p_id uuid,p_version integer,p_decision text,p_checks jsonb default null,p_reason text default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare s parking_scenes;l listings;begin
 if not gp_moderation_allowed() then raise exception 'FORBIDDEN';end if;select * into s from parking_scenes where id=p_id for update;if not found then raise exception 'NOT_FOUND';end if;if s.owner_id=auth.uid() or s.creator_id=auth.uid() then raise exception 'SCENE_PEER_REVIEW_REQUIRED';end if;if p_version is null or s.row_version<>p_version or s.state<>'pending_review' then raise exception 'VERSION_CONFLICT';end if;
 if coalesce(p_decision,'') not in ('approve','reject','changes_requested') or length(p_reason)>2000 or (p_decision<>'approve' and coalesce(length(p_reason),0)<1) then raise exception 'VALIDATION_ERROR';end if;select * into l from listings where id=s.listing_id for update;
 if p_decision='approve' then
 if p_checks is null or p_checks->>'geometryMatchesSources' is distinct from 'true' or p_checks->>'numbersAndLevelChecked' is distinct from 'true' or p_checks->>'conditionMatchesPhotos' is distinct from 'true' or p_checks->>'locationConsentChecked' is distinct from 'true' or l.last_published is null or not exists(select 1 from published_listings where id=l.id and payload->>'locationPrecision'='exact_opt_in') then raise exception 'SCENE_REVIEW_REQUIRED';end if;
 perform gp_validate_scene(s.manifest);perform gp_scene_mapping(s.manifest,l.last_published,true);
 if (select count(*) from parking_scene_sources x where x.id=any(s.evidence_ids) and exists(select 1 from storage.objects o where o.bucket_id='scene-sources' and o.name=x.object_key))<>cardinality(s.evidence_ids) then raise exception 'SCENE_EVIDENCE_REQUIRED';end if;
 update parking_scenes set state='retired',row_version=row_version+1,updated_at=now() where listing_id=s.listing_id and state='approved' and manifest->>'level'=s.manifest->>'level';
 end if;
 update parking_scenes set state=case p_decision when 'approve' then 'approved' when 'reject' then 'rejected' else 'changes_requested' end,row_version=row_version+1,approved_mapping=case when p_decision='approve' then l.last_published->'spaces' else null end,reviewed_at=now(),reviewer_id=auth.uid(),review_reason=p_reason,review_checks=p_checks,updated_at=now() where id=s.id returning * into s;
 insert into audit_events(actor_id,action,target_id,detail) values(auth.uid(),'scene.'||p_decision,s.id::text,p_reason);return to_jsonb(s);end;$$;
create function public.gp_scene_public(p_listing_id uuid,p_level integer default null) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$declare s parking_scenes;l listings;p jsonb;units jsonb;begin
 select * into l from listings where id=p_listing_id;if not found or l.last_published is null or not exists(select 1 from published_listings where id=l.id and payload->>'locationPrecision'='exact_opt_in') then return null;end if;
 select * into s from parking_scenes where listing_id=l.id and state='approved' and approved_mapping=l.last_published->'spaces' and (p_level is null or (manifest->>'level')::integer=p_level) order by reviewed_at desc limit 1;if not found then return null;end if;p=s.manifest;
 select jsonb_agg((u.value-'spaceId')||jsonb_build_object('id',l.id||':unit:'||v.ordinality)) into units from jsonb_array_elements(p->'spaces') u join jsonb_array_elements(l.last_published->'spaces') with ordinality v on v.value->>'id'=u.value->>'spaceId';
 p=jsonb_set(p,'{spaces}',units);p=jsonb_set(p,'{provenance}',jsonb_build_object('calibrated',true,'accuracyM',p->'provenance'->'accuracyM','controlDistancesCount',jsonb_array_length(p->'provenance'->'controlDistances'),'observedAt',p->'provenance'->'observedAt','publicSummary',p->'provenance'->'publicSummary'));
 return jsonb_build_object('id',s.id,'listingId',s.listing_id,'version',s.row_version,'fidelity','measured','reviewedAt',s.reviewed_at,'manifest',p);end;$$;
alter table public.parking_scene_sources enable row level security;alter table public.parking_scenes enable row level security;
create policy gp_scene_sources_read on public.parking_scene_sources for select to authenticated using(gp_active() and (owner_id=auth.uid() or gp_moderation_allowed()));
create policy gp_scene_sources_insert on public.parking_scene_sources for insert to authenticated with check(gp_verified() and uploader_id=auth.uid() and exists(select 1 from listings l where l.id=listing_id and l.seller_id=owner_id and (l.seller_id=auth.uid() or gp_moderation_allowed())) and object_key=auth.uid()||'/'||listing_id||'/'||id||case when mime='application/pdf' then '.pdf' else '.webp' end and (select count(*) from parking_scene_sources p where p.listing_id=parking_scene_sources.listing_id)<20);
create policy gp_scene_private_read on public.parking_scenes for select to authenticated using(gp_active() and (owner_id=auth.uid() or gp_moderation_allowed()));
revoke all on public.parking_scene_sources,public.parking_scenes from public,anon,authenticated;
grant select,insert on public.parking_scene_sources to authenticated;grant select on public.parking_scenes to authenticated;
revoke all on function public.gp_scene_polygon(jsonb),public.gp_validate_scene(jsonb),public.gp_scene_mapping(jsonb,jsonb,boolean),public.gp_scene_create(uuid,jsonb,uuid[],boolean),public.gp_scene_review(uuid,integer,text,jsonb,text),public.gp_scene_public(uuid,integer) from public,anon,authenticated;
grant execute on function public.gp_scene_create(uuid,jsonb,uuid[],boolean),public.gp_scene_review(uuid,integer,text,jsonb,text) to authenticated;grant execute on function public.gp_scene_public(uuid,integer) to anon,authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('scene-sources','scene-sources',false,10485760,array['application/pdf','image/webp']) on conflict(id) do nothing;
create policy gp_scene_source_upload on storage.objects for insert to authenticated with check(bucket_id='scene-sources' and exists(select 1 from public.parking_scene_sources s where s.object_key=name and s.uploader_id=auth.uid()) and gp_verified());
create policy gp_scene_source_download on storage.objects for select to authenticated using(bucket_id='scene-sources' and gp_active() and exists(select 1 from public.parking_scene_sources s where s.object_key=name and (s.owner_id=auth.uid() or gp_moderation_allowed())));
-- Enrich public listings and filter scene availability before pagination.
drop function public.gp_catalog(text,text,bigint,numeric,text,integer,integer);
create function public.gp_catalog(p_query text default '',p_type text default null,p_price_max bigint default null,p_area_min numeric default null,p_sort text default 'recent',p_offset integer default 0,p_limit integer default 24,p_scene boolean default false) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 with filtered as(select p.payload,p.created_at,p.id,gp_scene_public(p.id,null) is not null as has_scene from published_listings p where (coalesce(p_query,'')='' or lower((p.payload->>'city')||' '||(p.payload->>'district')||' '||(p.payload->>'title')) like '%'||lower(p_query)||'%') and (p_type is null or p.payload->>'type'=p_type) and (p_price_max is null or (p.payload->>'priceCents')::bigint<=p_price_max) and (p_area_min is null or not exists(select 1 from jsonb_array_elements(p.payload->'spaces') u where u->>'areaM2' is null or (u->>'areaM2')::numeric<p_area_min))), eligible as(select * from filtered where not coalesce(p_scene,false) or has_scene),page as(select * from eligible order by case when p_sort='price_asc' then (payload->>'priceCents')::bigint end asc,case when p_sort='price_desc' then (payload->>'priceCents')::bigint end desc,created_at desc,id limit least(50,greatest(1,p_limit)) offset greatest(0,p_offset)) select jsonb_build_object('items',coalesce((select jsonb_agg(payload||jsonb_build_object('sceneAvailable',has_scene)) from page),'[]'),'total',(select count(*) from eligible))$$;
revoke all on function public.gp_catalog(text,text,bigint,numeric,text,integer,integer,boolean) from public,anon,authenticated;grant execute on function public.gp_catalog(text,text,bigint,numeric,text,integer,integer,boolean) to anon,authenticated;
commit;
